      const $ = (s) => document.querySelector(s);
      const initial = new URLSearchParams(location.search);
      const state = {
        screen: initial.get("screen") || "shelf",
        theme: initial.get("theme") || "light",
        locale: initial.get("locale") || "en",
        motion: initial.get("motion") || "full",
        role: initial.get("role") || "student",
        chat: "empty",
        question: "",
        cardBack: false,
        studio: "empty",
        type: "summary",
        output: "en",
        topic: "Study sequence",
        intake: "empty",
        rights: false,
        filter: "all",
        selected: null,
        sourceOpen: false,
        depth: "concise",
        size: "short",
        sourceTitle: "Synthetic anatomy handout",
        sourceDescription: "Synthetic teaching fixture",
        reason: "",
        section: "appearance",
        epoch: 0,
      };
      const T = (en, ar) => (state.locale === "ar" ? ar : en);
      const esc = (x) =>
        String(x).replace(
          /[&<>"']/g,
          (c) =>
            ({
              "&": "&amp;",
              "<": "&lt;",
              ">": "&gt;",
              '"': "&quot;",
              "'": "&#39;",
            })[c],
        );
      const paths = {
        book: "M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h3z",
        shelf: "M4 4v16h16 M8 5v11h3V5z M14 6l3-1 3 10-3 1z",
        chat: "M4 4h16v12H9l-5 4z M8 8h8 M8 12h5",
        studio: "M4 5h16v14H4z M8 9h8 M8 13h4 M16 16v5 M13.5 18.5h5",
        quiz: "M5 3h14v18H5z M9 8l1.5 1.5L14 6 M9 14h6 M9 17h4",
        arrow: "M5 12h14 M14 7l5 5-5 5",
        back: "M19 12H5 M10 7l-5 5 5 5",
        file: "M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h4",
        user: "M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2",
        search: "M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M14.5 14.5L21 21",
        check: "M5 12l4 4L19 6",
        close: "M6 6l12 12 M18 6L6 18",
        clock: "M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 6v6l4 2",
        upload: "M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6",
        shield: "M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6",
        menu: "M4 6h16 M4 12h16 M4 18h16",
        info: "M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 10v6 M12 7h.01",
        alert: "M12 3L2 21h20z M12 9v5 M12 17h.01",
        settings: "M4 7h16 M4 17h16 M8 4v6 M16 14v6",
        sun: "M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1",
        globe:
          "M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c5 6 5 12 0 18-5-6-5-12 0-18",
        pause: "M8 4v16 M16 4v16",
      };
      const I = (name, extra = "") =>
        `<svg viewBox="0 0 24 24" class="icon ${extra}" aria-hidden="true"><path d="${paths[name] || paths.info}"/></svg>`;
      const B = (text, action, variant = "", icon = "", extra = "") =>
        `<button ${extra.includes('type="submit"') ? "" : 'type="button"'} class="btn ${variant}" data-action="${action}" ${extra}>${icon ? I(icon, icon === "arrow" || icon === "back" ? "directional" : "") : ""}${text}</button>`;
      const notice = (kind, title, body) =>
        `<div class="notice ${kind} feedback" role="${kind === "error" ? "alert" : "status"}">${I(kind === "success" ? "check" : kind === "error" ? "alert" : "info")}<div><strong>${title}</strong>${body ? `<p>${body}</p>` : ""}</div></div>`;
      const role = () =>
        state.screen === "intake"
          ? "leader"
          : state.screen === "admin"
            ? state.role === "second-admin"
              ? "second-admin"
              : "admin"
            : state.screen === "account"
              ? state.role
              : "student";
      const roleLabel = () =>
        ({
          student: T("Student", "طالب"),
          leader: T("Batch leader", "مسؤول الدفعة"),
          admin: T("Admin", "مسؤول"),
          "second-admin": T("Second admin", "المسؤول الثاني"),
        })[role()];
      const navItem = (label, icon, target, active) =>
        `<button class="navlink ${active ? "active" : ""}" data-screen="${target}" ${active ? 'aria-current="page"' : ""} aria-label="${label}">${I(icon)}<span>${label}</span></button>`;
      function navigation() {
        const r = role();
        if (r === "leader")
          return (
            navItem(
              T("Source intake", "استقبال المصادر"),
              "upload",
              "intake",
              state.screen === "intake",
            ) + navItem(T("History", "السجل"), "clock", "history", false)
          );
        if (r.includes("admin"))
          return (
            navItem(
              T("Decision queue", "قائمة القرارات"),
              "shield",
              "admin",
              state.screen === "admin",
            ) +
            navItem(T("Catalog", "الدليل الدراسي"), "book", "catalog", false) +
            navItem(T("Sources", "المصادر"), "file", "sources", false) +
            navItem(
              T("Usage & capacity", "الاستخدام والسعة"),
              "settings",
              "usage",
              false,
            )
          );
        return (
          navItem(
            T("Study", "المذاكرة"),
            "book",
            "shelf",
            state.screen === "chat" || state.screen === "studio",
          ) +
          navItem(
            T("Subjects", "المواد"),
            "shelf",
            "shelf",
            state.screen === "shelf",
          )
        );
      }
      function shell(body) {
        return `<div class="shell"><aside class="spine"><a class="brand" href="?screen=shelf" aria-label="UniMind"><img src="../concepts/assets/folio-dark.svg" alt="" /><span class="brand-name">UniMind</span></a><nav aria-label="${T("Main navigation", "التنقل الرئيسي")}">${navigation()}</nav><div class="identity"><button class="navlink ${state.screen === "account" ? "active" : ""}" data-screen="account">${I("user")}<span>${T("Account", "الحساب")}</span></button><div class="inline"><span class="avatar" aria-hidden="true">${role() === "student" ? "S" : role() === "leader" ? "L" : role() === "second-admin" ? "A2" : "A"}</span><div class="identity-copy"><strong style="font-size:13px">${roleLabel()}</strong><div class="meta">${T("Synthetic account", "حساب تجريبي")}</div></div></div><p class="wordmark" lang="en" dir="ltr">Study deeper<br />Go further.</p></div></aside><header class="mobilebar"><span class="mobile-brand"><img src="../concepts/assets/folio-dark.svg" alt="" /><span>UniMind</span></span><span class="role-label">${roleLabel()}</span>${B(`<span class="sr-only">${T("Open navigation", "فتح التنقل")}</span>`, "menu", "quiet icon-btn", "menu")}</header><main id="main" class="main" tabindex="-1"><div class="page">${body}</div></main><nav class="bottomnav" aria-label="${T("Primary navigation", "التنقل الأساسي")}"><button data-screen="${role() === "leader" ? "intake" : role().includes("admin") ? "admin" : "shelf"}" class="${state.screen !== "account" ? "active" : ""}">${I(role() === "leader" ? "upload" : role().includes("admin") ? "shield" : "shelf")}<span>${role() === "leader" ? T("Intake", "الاستقبال") : role().includes("admin") ? T("Decisions", "القرارات") : T("Subjects", "المواد")}</span></button><button data-screen="account" class="${state.screen === "account" ? "active" : ""}">${I("user")}<span>${T("Account", "الحساب")}</span></button><button data-action="menu">${I("menu")}<span>${T("More", "المزيد")}</span></button></nav></div>`;
      }
      function unit() {
        return `<div class="breadcrumb">${B(T("Subjects", "المواد"), "subjects", "quiet", "back")}<span>/</span><span>${T("Anatomy", "التشريح")}</span></div><header class="unithead"><div><h1>${T("Anatomy", "التشريح")}</h1><p class="meta">${T("8 sample materials · Ready", "٨ مواد تجريبية · جاهزة")}</p></div>${B(T("Switch unit", "تغيير الوحدة"), "subjects", "quiet", "shelf")}</header><nav class="tabs" aria-label="${T("Unit tools", "أدوات الوحدة")}">${["materials", "chat", "studio", "quiz"].map((s) => `<button data-screen="${s}" ${state.screen === s ? 'aria-current="page"' : ""}>${{ materials: T("Materials", "المواد الدراسية"), chat: T("Chat", "المحادثة"), studio: T("Studio", "الاستوديو"), quiz: T("Quiz", "الاختبار") }[s]}</button>`).join("")}</nav>`;
      }
      function shelf() {
        const subjects = [
          ["Anatomy", "التشريح"],
          ["Biochemistry", "الكيمياء الحيوية"],
          ["Physiology", "علم وظائف الأعضاء"],
          ["Pathology", "علم الأمراض"],
          ["Pharmacology", "علم الأدوية"],
        ];
        return `<header class="page-heading"><h1>${T("Your subjects", "موادك الدراسية")}</h1><p class="muted">${T("Choose a subject. Every answer stays connected to its approved materials.", "اختر مادة. تظل كل إجابة مرتبطة بمصادرها المعتمدة.")}</p></header><div class="collection"><section class="collection-main" aria-label="${T("Subjects", "المواد")}"><div class="spread"><h2>${T("Medicine · Modules", "الطب · الوحدات")}</h2><label class="search">${I("search")}<input type="search" id="subject-search" aria-label="${T("Find a subject", "البحث عن مادة")}" placeholder="${T("Find a subject", "ابحث عن مادة")}" /></label></div><div class="subject-index" id="subject-list">${subjects.map(([en, ar]) => `<button class="subject-row" data-action="open-subject" data-name="${en.toLowerCase()} ${ar}" aria-label="${T("Open " + en, "فتح " + ar)}"><span class="folio-mark" aria-hidden="true"></span><div class="subject-copy"><h3>${T(en, ar)}</h3><p class="meta">${T("8 sample materials", "٨ مواد تجريبية")}</p></div><span class="tag ready">${T("Ready", "جاهزة")}</span>${I("arrow", "directional")}</button>`).join("")}</div><p id="subject-empty" class="notice" hidden>${T("No matching subjects. Try another name.", "لا توجد مواد مطابقة. جرّب اسمًا آخر.")}</p></section><aside class="orientation"><svg class="folio-emblem" viewBox="0 0 180 140" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M25 26h48q17 0 17 16v74q-8-11-22-11H25z M155 26h-48q-17 0-17 16v74q8-11 22-11h43z M36 42h30 M36 53h30 M36 64h23 M107 42h35 M107 53h35 M107 64h25"/><path d="M136 26v28l-7-6-7 6V26" fill="currentColor"/><path d="M18 32v80h50q14 0 22 10 8-10 22-10h50V32" opacity=".45"/></svg><h2>${T("Start with the source.", "ابدأ من المصدر.")}</h2><p>${T("Read your materials, ask a question, then turn what you understand into a study artifact.", "اقرأ موادك، واسأل سؤالًا، ثم حوّل ما فهمته إلى أداة للمذاكرة.")}</p><div class="context-note"><strong>${T("Your academic context", "سياقك الدراسي")}</strong><p class="meta">${T("Medicine · Synthetic cohort", "الطب · مجموعة تجريبية")}</p>${B(T("Edit in Account", "تعديل من الحساب"), "account", "quiet", "settings")}</div></aside></div>`;
      }
      const samplePrompt = () =>
        T(
          "Explain the sample unit's study sequence.",
          "اشرح ترتيب المذاكرة في الوحدة التجريبية.",
        );
      const sampleAnswer = () =>
        T(
          "The synthetic handout says to identify the labelled structures, then compare the two diagrams. This fixed example uses only the sample handout.",
          "الملزمة التجريبية تطلب تحديد الأجزاء المسماة ثم مقارنة الرسمين. هذا مثال ثابت من الملزمة فقط.",
        );
      function sourceContent(reveal = false) {
        return `<div class="source-inspector ${reveal ? "reveal" : ""}"><div class="spread"><h2 tabindex="-1" id="source-heading">${T("Source excerpt", "مقتطف من المصدر")}</h2><span class="pill">${T("Page 3", "صفحة ٣")}</span></div><h3>${T("Synthetic anatomy handout", "ملزمة التشريح التجريبية")}</h3><p class="meta">${T("Approved sample material", "مادة تجريبية معتمدة")}</p><blockquote class="source-quote">${T("Identify the labelled structures, then compare the two diagrams.", "حدد الأجزاء المسماة، ثم قارن الرسمين.")}</blockquote><div class="source-rule"></div><p>${T("The source supports this sequence. It does not specify the timing of either step.", "المصدر يدعم هذا الترتيب، لكنه لا يحدد وقت كل خطوة.")}</p></div>`;
      }
      function margin() {
        return `<aside class="margin-panel" id="source-panel" aria-label="${T("Evidence margin", "هامش الأدلة")}">${state.chat === "supported" ? sourceContent() : `<h2>${T("An evidence margin", "هامش الأدلة")}</h2><p>${T("When an answer cites a source, inspect its excerpt here without losing your question.", "عندما تستشهد الإجابة بمصدر، راجع مقتطفه هنا دون فقدان سؤالك.")}</p><div class="source-rule"></div><div class="inline">${I("file")}<span class="meta">${T("8 sample materials available", "٨ مواد تجريبية متاحة")}</span></div>`}</aside>`;
      }
      function chatBody() {
        if (state.chat === "loading")
          return `<p class="question">${esc(state.question)}</p><div class="reading-empty" role="status" aria-live="polite"><h2>${T("Checking the sample materials…", "جارٍ مراجعة المواد التجريبية…")}</h2><p>${T("Your question remains here. You can cancel this example.", "يبقى سؤالك هنا. يمكنك إلغاء هذا المثال.")}</p><div class="busy-line" style="width:100%"></div>${B(T("Cancel", "إلغاء"), "cancel-chat", "quiet")}</div>`;
        if (state.chat === "error")
          return (
            notice(
              "error",
              T("The answer could not be loaded.", "تعذّر تحميل الإجابة."),
              T(
                "Your question has been kept. Retry when you are ready.",
                "احتُفظ بسؤالك. أعد المحاولة عندما تكون جاهزًا.",
              ),
            ) +
            B(
              T("Retry answer", "إعادة تحميل الإجابة"),
              "retry-chat",
              "quiet",
              "arrow",
            )
          );
        if (state.chat === "supported")
          return `<p class="question">${esc(state.question || samplePrompt())}</p><article class="answer"><span class="tag ready">${T("Supported by a source", "مدعوم بمصدر")}</span><h3>${T("Identify, then compare.", "حدّد، ثم قارن.")}</h3><p>${sampleAnswer()}</p><button class="citation" data-action="citation" aria-label="${T("Inspect source, handout page 3", "عرض المصدر، الملزمة صفحة ٣")}">${I("file")}${T("Handout · p. 3", "الملزمة · ص. ٣")}</button></article>`;
        return `<div class="reading-empty">${I("chat")}<h2>${T("A question worth understanding.", "سؤال يستحق الفهم.")}</h2><p>${T("Ask about Anatomy. Answers use the approved materials for this unit and show what supports them.", "اسأل عن التشريح. تستخدم الإجابات مواد هذه الوحدة المعتمدة وتوضح ما يدعمها.")}</p><div class="prompts"><button class="suggestion" data-action="suggest">${samplePrompt()}${I("arrow", "directional")}</button><button class="suggestion" data-action="demo-error">${T("Preview a recoverable error", "معاينة خطأ قابل للاسترداد")}${I("arrow", "directional")}</button></div></div>`;
      }
      function chat() {
        return (
          unit() +
          `<div class="workspace"><section class="paper chat-work" aria-label="${T("Study conversation", "محادثة المذاكرة")}"><div class="thread-head"><h2>${T("Study conversation", "محادثة المذاكرة")}</h2><div class="inline gap8">${B(T("Sources", "المصادر"), "citation", "quiet mobile-sources", "file")}${B(T("New session", "جلسة جديدة"), "new-chat", "quiet")}</div></div><div class="thread" id="thread">${chatBody()}</div><form class="composer" id="chat-form"><label class="sr-only" for="message">${T("Message", "رسالة")}</label><textarea id="message" placeholder="${T("Ask about your materials…", "اسأل عن موادك…")}" ${state.chat === "loading" ? "disabled" : ""}>${state.chat === "error" ? esc(state.question) : ""}</textarea>${B(T("Send", "إرسال"), "send", "primary", "arrow", `type="submit" ${state.chat === "loading" ? "disabled" : ""}`)}</form><p class="chat-foot">${T("Shared study session · source-grounded answers", "جلسة مذاكرة مشتركة · إجابات من المصادر")}</p></section>${margin()}</div>`
        );
      }
      const artifacts = [
        ["summary", "Structured summary", "ملخص منظم"],
        ["guide", "Study guide", "دليل مذاكرة"],
        ["practice", "Practice questions", "أسئلة تدريب"],
        ["flashcards", "Flashcards", "بطاقات مراجعة"],
        ["revision", "Revision pack", "حزمة مراجعة"],
        ["quiz", "MCQ quiz", "اختبار اختيار من متعدد"],
      ];
      function output() {
        if (state.studio === "loading")
          return `<div class="reading-empty" role="status"><h2>${T("Preparing your example…", "جارٍ إعداد المثال…")}</h2><p>${T("Checking the selected materials. No progress percentage is assumed.", "جارٍ مراجعة المواد المختارة. لا نفترض نسبة تقدم.")}</p><div class="busy-line" style="width:100%"></div><div class="placeholder-lines" style="width:100%" aria-hidden="true"><span></span><span></span><span></span></div>${B(T("Cancel", "إلغاء"), "cancel-studio", "quiet")}</div>`;
        if (state.studio === "error")
          return `<div class="stack">${notice("error", T("This artifact could not be prepared.", "تعذّر إعداد هذه الأداة."), T("Your topic and options are preserved.", "احتُفظ بالموضوع والخيارات."))}${B(T("Retry generation", "إعادة الإعداد"), "generate", "quiet", "arrow")}</div>`;
        if (state.studio === "empty")
          return `<div class="reading-empty">${I("studio")}<h2>${T("Give your understanding a form.", "امنح فهمك شكلًا.")}</h2><p>${T("Choose an artifact and a topic. The result will stay alongside its source evidence.", "اختر أداة وموضوعًا. ستبقى النتيجة بجانب أدلة مصادرها.")}</p></div>`;
        if (state.type === "flashcards")
          return `<div class="stack result-content"><div class="spread"><span class="meta">${T("Card 1 of 1 · sample", "بطاقة ١ من ١ · مثال")}</span>${B(T("Sources", "المصادر"), "citation", "quiet", "file")}</div><button class="flashcard ${state.cardBack ? "flip" : ""}" data-action="flip" aria-label="${T("Turn flashcard", "قلب البطاقة")}" aria-pressed="${state.cardBack}"><span class="meta">${state.cardBack ? T("Answer", "الإجابة") : T("Question", "السؤال")}</span><strong class="card-copy" dir="${state.output === "ar" ? "rtl" : "ltr"}">${state.cardBack ? (state.output === "ar" ? "حدد الأجزاء المسماة، ثم قارن الرسمين." : "Identify the labelled structures, then compare the two diagrams.") : state.output === "ar" ? "ما الخطوة التي تسبق مقارنة الرسمين؟" : "What comes before comparing the diagrams?"}</strong><span class="meta">${T("Click or press Space to turn", "اضغط أو استخدم مفتاح المسافة للقلب")}</span></button></div>`;
        return `<article class="answer result-content" dir="${state.output === "ar" ? "rtl" : "ltr"}"><span class="tag ready">${T("Fixed example · source-supported", "مثال ثابت · مدعوم بمصدر")}</span><h2 style="margin-block:10px 20px">${state.output === "ar" ? "ترتيب المذاكرة" : "Study sequence"}</h2><h3>${state.output === "ar" ? "ابدأ بتحديد الأجزاء" : "Begin with identification"}</h3><p style="margin-top:10px">${state.output === "ar" ? "حدد الأجزاء المسماة في الملزمة التجريبية قبل مقارنة الرسمين." : "Identify the labelled structures in the synthetic handout before comparing the two diagrams."}</p><h3 style="margin-top:24px">${state.output === "ar" ? "ثم قارن الرسمين" : "Then compare the diagrams"}</h3><p style="margin-top:10px">${state.output === "ar" ? "المصدر لا يحدد وقت كل خطوة." : "The source does not specify the timing of either step."}</p><button class="citation" data-action="citation">${I("file")}${T("Handout · p. 3", "الملزمة · ص. ٣")}</button></article>`;
      }
      function studio() {
        return (
          unit() +
